import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    # knot values with zero endpoints
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    # ||f*f||_2^2
    a = Lp[:-1]
    b = Lp[1:]
    l2 = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = Lp.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def _tri(N, w):
    x = np.linspace(-1.0, 1.0, N)
    return np.maximum(0.0, 1.0 - np.abs(x) / w)


