def _local_sweeps(h, t0, budget_seconds, margin=1.0):
    """Full-resolution coordinate and pairwise mass-shift sweeps."""
    h = np.array(h, dtype=float)
    N = h.size
    best = _R_from_h(h)
    factors = (0.90, 0.95, 0.98, 1.02, 1.05, 1.10)
    deltas = (-0.05, -0.02, -0.01, 0.01, 0.02, 0.05)

    for sweep in range(10):
        improved = False
        # single-coordinate multiplicative and neighbor-average moves
        for i in range(N):
            if time.process_time() - t0 > budget_seconds - margin:
                return h, best
            orig = h[i]
            # multiplicative factors
            for f in factors:
                h[i] = orig * f
                v = _R_from_h(h)
                if v > best:
                    best = v
                    orig = h[i]
                    improved = True
                else:
                    h[i] = orig
            # neighbor average
            if 0 < i < N - 1:
                h[i] = 0.5 * (h[i - 1] + h[i + 1])
                v = _R_from_h(h)
                if v > best:
                    best = v
                    orig = h[i]
                    improved = True
                else:
                    h[i] = orig
            h[i] = orig

        # pairwise mass shifts
        hmax = h.max()
        if hmax <= 0:
            break
        for i in range(N - 1):
            if time.process_time() - t0 > budget_seconds - margin:
                return h, best
            a0, b0 = h[i], h[i + 1]
            for d in deltas:
                step = d * hmax
                na = a0 + step
                nb = b0 - step
                if na < 0 or nb < 0:
                    continue
                h[i], h[i + 1] = na, nb
                v = _R_from_h(h)
                if v > best:
                    best = v
                    a0, b0 = na, nb
                    improved = True
                else:
                    h[i], h[i + 1] = a0, b0
            # set both to average
            avg = 0.5 * (a0 + b0)
            h[i], h[i + 1] = avg, avg
            v = _R_from_h(h)
            if v > best:
                best = v
                improved = True
            else:
                h[i], h[i + 1] = a0, b0

        if not improved:
            break

    return h, best


