def _R_from_h(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    L2 = L * L
    num = (L2[:-1] + L[:-1] * L[1:] + L2[1:]).sum() / 3.0
    den = (s * s) * L.max()
    if den <= 0:
        return 0.0
    return num / den


