        for i in range(N - 1):
            m = min(h[i], h[i + 1])
            if m <= 0:
                continue
            for d in ds:
                for sign in (1.0, -1.0):
                    step = sign * d * m
                    trial = h.copy()
                    trial[i] = h[i] - step
