                    if trial[i] < 0 or trial[i + 1] < 0:
                        continue
                    v = _R_from_h(trial)
                    if v > cur_v:
                        cur_v = v
                        h = trial
                        improved = True
        if not improved:
            break

    best_h = h
    best_v = cur_v

    out = best_h.copy()
    if out.sum() <= 0:
        out = np.ones(N)
    return out

